      {
        "step": "Find processes holding deleted files",
        "hypothesis": "The 70GB file deleted via 'rm' is still being held open by a process, preventing space reclamation.",
        "how_to_check": "lsof +L1 | grep '/data' or lsof -nP | grep '(deleted)'"
