      {
        "step": "Compare df and du output",
        "hypothesis": "Discrepancy between df and du confirms space is held by unlinked but open files.",
        "how_to_check": "df -h /data && du -xhs /data"
      },
      {
        "step": "Identify top growing directories",
        "hypothesis": "A specific application or log is driving the 0.488 GiB/hour growth rate.",
        "how_to_check": "du -xh --max-depth=2 /data | sort -h | tail"
      }
    ],
    "root_cause_hypotheses": [
      "A process is holding an open file descriptor to a 70GB log file that was deleted using 'rm' instead of being rotated or truncated.",
      "Runaway application logging is causing steady growth of ~500MB/hour."
    ],
